/**
 * Menu artwork: the founder-approved Stitch key art and fighter portraits, served from the build (WebP, two
 * widths each; generated by tools/ui/build_menu_art.py, never hand-edited). The portraits are concept art
 * for the menus only: they establish no gameplay, and a fighter without one falls back to the rendered bust.
 */
import type { CharacterId } from '../../sim';
import keyart768 from '../../assets/ui/keyart-768.webp';
import keyart1376 from '../../assets/ui/keyart-1376.webp';
import sb360 from '../../assets/ui/fighter-streetBaller-360.webp';
import sb720 from '../../assets/ui/fighter-streetBaller-720.webp';
import lb360 from '../../assets/ui/fighter-lekkiBoy-360.webp';
import lb720 from '../../assets/ui/fighter-lekkiBoy-720.webp';
import cq360 from '../../assets/ui/fighter-campusQueen-360.webp';
import cq720 from '../../assets/ui/fighter-campusQueen-720.webp';

export interface Art {
  src: string;
  srcSet: string;
}

export const KEY_ART: Art = { src: keyart1376, srcSet: `${keyart768} 768w, ${keyart1376} 1376w` };

const FIGHTER_ART: Partial<Record<CharacterId, Art>> = {
  streetBaller: { src: sb720, srcSet: `${sb360} 360w, ${sb720} 720w` },
  lekkiBoy: { src: lb720, srcSet: `${lb360} 360w, ${lb720} 720w` },
  campusQueen: { src: cq720, srcSet: `${cq360} 360w, ${cq720} 720w` },
};

/** The full-body menu portrait of a fighter, or null (use the rendered bust instead). */
export const fighterArt = (id: CharacterId): Art | null => FIGHTER_ART[id] ?? null;
